  readonly Dictionary<string,ImageSource> icons=new Dictionary<string,ImageSource>();
  UIElement IconFor(Game g){ImageSource source=null;if(!icons.TryGetValue(g.executable??"",out source)){try{using(var icon=System.Drawing.Icon.ExtractAssociatedIcon(g.executable)){source=Imaging.CreateBitmapSourceFromHIcon(icon.Handle,Int32Rect.Empty,System.Windows.Media.Imaging.BitmapSizeOptions.FromEmptyOptions());source.Freeze();}}catch{}icons[g.executable??""]=source;}if(source!=null)return new Image{Source=source,Width=32,Height=32};var text=U.Text(new string(g.name.Take(2).ToArray()).ToUpperInvariant(),16,"#007AFF",true);text.HorizontalAlignment=HorizontalAlignment.Center;return text;}
