  public void EditGame(Game existing,string file){U.Safe(this,()=>{
   Game draft=existing==null?new Game():new Game{id=existing.id,name=existing.name,executable=existing.executable,arguments=existing.arguments,workingDirectory=existing.workingDirectory,originalShortcut=existing.originalShortcut,trackingDirectory=existing.trackingDirectory,processNames=existing.processNames,enabled=existing.enabled};
   if(file!=null)FillFromFile(draft,file);
   var w=U.Dialog(this,L.T(existing==null?"add":"edit"),660);var panel=new StackPanel{Margin=new Thickness(26)};var name=U.Field(panel,"name",draft.name);var target=U.Field(panel,"file",draft.executable);var advanced=new StackPanel();var args=U.Field(advanced,"args",draft.arguments);var work=U.Field(advanced,"workdir",draft.workingDirectory);var proc=U.Field(advanced,"process",string.Join(", ",draft.processNames));var dir=U.Field(advanced,"directory",draft.trackingDirectory);
   Action fill=()=>{name.Text=draft.name??"";target.Text=draft.executable??"";args.Text=draft.arguments??"";work.Text=draft.workingDirectory??"";proc.Text=string.Join(", ",draft.processNames);dir.Text=draft.trackingDirectory??"";};
   var tools=new WrapPanel();tools.Children.Add(U.Button(L.T("desktopShortcut"),()=>U.Safe(w,()=>{string selected=PickDesktopShortcut(w);if(selected!=null){FillFromFile(draft,selected);fill();}})));tools.Children.Add(U.Button(L.T("browse"),()=>U.Safe(w,()=>{var picker=new Microsoft.Win32.OpenFileDialog{Filter="EXE / LNK|*.exe;*.lnk|EXE|*.exe|LNK|*.lnk|All files|*.*"};if(picker.ShowDialog(w)==true){FillFromFile(draft,picker.FileName);fill();}})));tools.Children.Add(U.Button(L.T("chooseRunning"),()=>{Observed p=PickProcess(w);if(p!=null){if(string.IsNullOrWhiteSpace(name.Text))name.Text=p.Name;if(string.IsNullOrWhiteSpace(target.Text))target.Text=p.Path;proc.Text=p.Name;dir.Text=Path.GetDirectoryName(p.Path);if(string.IsNullOrWhiteSpace(work.Text))work.Text=dir.Text;}}));panel.Children.Add(tools);
   panel.Children.Add(new Expander{Header=L.T("advanced"),Content=advanced,Margin=new Thickness(0,16,0,16)});var enabled=new CheckBox{Content=L.T("enabled"),IsChecked=draft.enabled,Margin=new Thickness(0,0,0,18)};panel.Children.Add(enabled);
   panel.Children.Add(U.Row(U.Button(L.T("save"),()=>U.Safe(w,()=>{
    draft.name=name.Text.Trim();draft.executable=target.Text.Trim();draft.arguments=args.Text;draft.workingDirectory=work.Text.Trim();draft.processNames=proc.Text.Split(new[]{',','，',';'},StringSplitOptions.RemoveEmptyEntries).Select(n=>Path.GetFileNameWithoutExtension(n.Trim())).ToArray();draft.trackingDirectory=dir.Text.Trim();draft.enabled=enabled.IsChecked==true;
    if(draft.processNames.Length==0&&File.Exists(draft.executable))draft.processNames=new[]{Path.GetFileNameWithoutExtension(draft.executable)};if(string.IsNullOrWhiteSpace(draft.trackingDirectory)&&File.Exists(draft.executable))draft.trackingDirectory=Path.GetDirectoryName(draft.executable);if(string.IsNullOrWhiteSpace(draft.workingDirectory))draft.workingDirectory=Path.GetDirectoryName(draft.executable);
    if(!File.Exists(draft.executable)){MessageBox.Show(w,L.T("invalid"),L.T("title"));return;}try{Store.ValidateGame(draft);}catch{MessageBox.Show(w,L.T("invalid"),L.T("title"));return;}
    lock(app.Store.Gate){if(app.Store.Config.games.Any(g=>g.id!=draft.id&&string.Equals(g.executable,draft.executable,StringComparison.OrdinalIgnoreCase))){MessageBox.Show(w,L.T("duplicate"),L.T("title"));return;}int index=app.Store.Config.games.FindIndex(g=>g.id==draft.id);if(index<0)app.Store.Config.games.Add(draft);else app.Store.Config.games[index]=draft;app.Store.SaveConfig();}app.Tracker.Changed();w.Close();Render();
   }),true),U.Button(L.T("cancel"),()=>w.Close())));var actions=(UIElement)panel.Children[panel.Children.Count-1];panel.Children.Remove(actions);((FrameworkElement)actions).Margin=new Thickness(26,10,26,20);var layout=new DockPanel();DockPanel.SetDock(actions,Dock.Bottom);layout.Children.Add(actions);layout.Children.Add(new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});w.Content=layout;w.AllowDrop=true;w.Drop+=(o,e)=>{if(e.Data.GetDataPresent(DataFormats.FileDrop))U.Safe(w,()=>{FillFromFile(draft,((string[])e.Data.GetData(DataFormats.FileDrop))[0]);fill();});};w.ShowDialog();
  });}
  public static void FillFromFile(Game draft,string file){string target=file,args="",work=Path.GetDirectoryName(file);if(string.Equals(Path.GetExtension(file),".lnk",StringComparison.OrdinalIgnoreCase)){dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));dynamic link=shell.CreateShortcut(file);try{target=(string)link.TargetPath;args=(string)link.Arguments;work=(string)link.WorkingDirectory;draft.originalShortcut=file;}finally{Marshal.FinalReleaseComObject(link);Marshal.FinalReleaseComObject(shell);}}
   if(!File.Exists(target)||!string.Equals(Path.GetExtension(target),".exe",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException(L.T("invalid"));draft.executable=Path.GetFullPath(target);draft.arguments=args;draft.workingDirectory=string.IsNullOrWhiteSpace(work)?Path.GetDirectoryName(target):work;draft.trackingDirectory=Path.GetDirectoryName(target);draft.processNames=new[]{Path.GetFileNameWithoutExtension(target)};string description=FileVersionInfo.GetVersionInfo(target).FileDescription;draft.name=string.IsNullOrWhiteSpace(description)?Path.GetFileNameWithoutExtension(target):description;
  }
  public static List<DesktopLink> DesktopShortcuts(params string[] directories){var result=new List<DesktopLink>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string directory in directories.Where(d=>!string.IsNullOrWhiteSpace(d)&&Directory.Exists(d))){foreach(string file in Directory.GetFiles(directory,"*.lnk",SearchOption.TopDirectoryOnly)){if(seen.Add(file))result.Add(new DesktopLink{Path=file,Label=Path.GetFileNameWithoutExtension(file)});}}return result.OrderBy(x=>x.Label,StringComparer.CurrentCultureIgnoreCase).ToList();}
  string PickDesktopShortcut(Window owner){string selected=null;var links=DesktopShortcuts(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory));var w=U.Dialog(owner,L.T("desktopShortcut"),620);w.Height=520;w.SizeToContent=SizeToContent.Manual;var panel=new DockPanel{Margin=new Thickness(22)};var top=new StackPanel();top.Children.Add(U.Text(L.T("desktopPickInfo"),13,"#6E6E73"));var search=new TextBox{Margin=new Thickness(0,12,0,12),Padding=new Thickness(8)};top.Children.Add(search);DockPanel.SetDock(top,Dock.Top);panel.Children.Add(top);var list=new ListBox{DisplayMemberPath="Label",HorizontalContentAlignment=HorizontalAlignment.Stretch};Action filter=()=>list.ItemsSource=links.Where(x=>x.Label.IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0).ToList();search.TextChanged+=(o,e)=>filter();var bottom=U.Row(U.Button(L.T("save"),()=>{var item=list.SelectedItem as DesktopLink;if(item!=null){selected=item.Path;w.Close();}},true),U.Button(L.T("cancel"),()=>w.Close()));DockPanel.SetDock(bottom,Dock.Bottom);panel.Children.Add(bottom);panel.Children.Add(list);filter();w.Content=panel;w.ShowDialog();return selected;}
  Observed PickProcess(Window owner){Observed selected=null;var w=U.Dialog(owner,L.T("chooseRunning"),760);w.Height=550;w.SizeToContent=SizeToContent.Manual;var panel=new DockPanel{Margin=new Thickness(22)};var top=new StackPanel();top.Children.Add(U.Text(L.T("startPick"),13,"#86868B"));var search=new TextBox{Margin=new Thickness(0,10,0,12),Padding=new Thickness(8)};top.Children.Add(search);DockPanel.SetDock(top,Dock.Top);panel.Children.Add(top);var list=new ListBox{DisplayMemberPath="Display",HorizontalContentAlignment=HorizontalAlignment.Stretch};List<Observed> values=null;Action refresh=()=>{values=Tracker.ScanVisibleWindows();list.ItemsSource=values.Where(p=>p.Display.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).ToList();};var bottom=U.Row(U.Button(L.T("refresh"),refresh),U.Button(L.T("save"),()=>{selected=list.SelectedItem as Observed;if(selected!=null)w.Close();},true));DockPanel.SetDock(bottom,Dock.Bottom);panel.Children.Add(bottom);panel.Children.Add(list);search.TextChanged+=(o,e)=>{if(values!=null)list.ItemsSource=values.Where(p=>p.Display.IndexOf(search.Text,StringComparison.OrdinalIgnoreCase)>=0).ToList();};refresh();w.Content=panel;w.ShowDialog();return selected;}
  void Launch(Game g){U.Safe(this,()=>{if(!File.Exists(g.executable))throw new FileNotFoundException(L.T("notFound"));using(var p=Process.Start(new ProcessStartInfo(g.executable,g.arguments??""){WorkingDirectory=g.workingDirectory,UseShellExecute=true})){};app.Tracker.Changed();});}
  void Manual(Game g){var w=U.Dialog(this,L.T("manual"),460);var panel=new StackPanel{Margin=new Thickness(24)};var input=U.Field(panel,"manualHint","");panel.Children.Add(U.Text(L.T("manualNote"),12,"#86868B"));panel.Children.Add(U.Button(L.T("save"),()=>{double minutes;if(!double.TryParse(input.Text,out minutes)||double.IsNaN(minutes)||double.IsInfinity(minutes)||minutes<=0||minutes>52560000)return;var now=DateTimeOffset.Now;app.Store.Finish(new Session{gameId=g.id,gameName=g.name,status="manual",runKey="manual-"+Guid.NewGuid().ToString("N"),startTime=now.ToString("o"),endTime=now.ToString("o"),lastHeartbeat=now.ToString("o"),durationSeconds=minutes*60});w.Close();Render();},true));w.Content=panel;w.ShowDialog();}
  void Help(){var w=U.Dialog(this,L.T("help"),640);var panel=new StackPanel{Margin=new Thickness(26)};panel.Children.Add(U.Text(L.T("title"),24,"#1D1D1F",true));string path=Path.Combine(App.Base,"docs","help."+L.Language+".txt");panel.Children.Add(new TextBlock{Text=File.Exists(path)?File.ReadAllText(path):L.T("welcomeBody"),TextWrapping=TextWrapping.Wrap,LineHeight=24,Margin=new Thickness(0,18,0,0)});w.Content=new ScrollViewer{Content=panel,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};w.ShowDialog();}
 }
